def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    absolute_change = v1 - v2
    percentage_change = (absolute_change / v2) * 100

    return {
        "value": percentage_change,
        "trace": {
            "v1": v1,
            "v2": v2,
            "absolute_change": absolute_change,
            "formula": "((v1 - v2) / v2) * 100",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
